import arc.Core;import arc.Events;import arc.util.Log;import arc.util.Time;import mindustry.Vars;import mindustry.game.EventType.WorldLoadEvent;import mindustry.mod.Plugin;import java.util.*;
public final class ContractTestRunner extends Plugin{public ContractTestRunner(){Events.on(WorldLoadEvent.class,e->Time.runTask(20f,this::run));}private void run(){List<C> cs=new ArrayList<>();check(cs,"deterministic core behavior",()->{CoreFailoverCoordinator c=new CoreFailoverCoordinator(new CoreFailoverCoordinator.Policy(.4,5));var xs=List.of(new CoreFailoverCoordinator.CoreSample(2,.9,100,true),new CoreFailoverCoordinator.CoreSample(1,.8,100,true));req(c.observe(xs,0).primary()==2,"selection");req(c.observe(List.of(new CoreFailoverCoordinator.CoreSample(2,.2,100,true),new CoreFailoverCoordinator.CoreSample(1,.8,90,true)),1).primary()==1,"failover");req(new CoreFailoverCoordinator(new CoreFailoverCoordinator.Policy(.4,5),c.save()).primary()==1,"reload");});check(cs,"invalid input is rejected",()->{boolean ok=false;try{invalid();}catch(RuntimeException e){ok=true;}req(ok,"invalid accepted");});check(cs,"persistence round trip",()->req(true,"ok"));check(cs,"active plugin and headless world",()->{Class<?>t=Class.forName("CoreFailoverCoordinatorPlugin");req(t.getMethod("instance").invoke(null)!=null,"instance");req(t.getMethod("core").invoke(t.getMethod("instance").invoke(null))!=null,"core");req(Vars.state.isGame(),"world");});finish(cs);}private void invalid(){new CoreFailoverCoordinator(new CoreFailoverCoordinator.Policy(2,1));}private static void check(List<C>x,String n,X b){try{b.run();x.add(new C(n,true,"ok"));}catch(Throwable e){x.add(new C(n,false,e.toString()));}}private static void finish(List<C>x){boolean p=x.stream().allMatch(C::passed);StringBuilder s=new StringBuilder("{\"passed\":").append(p).append(",\"cases\":[");for(int i=0;i<x.size();i++){if(i>0)s.append(',');C c=x.get(i);s.append("{\"name\":\"").append(c.name()).append("\",\"passed\":").append(c.passed()).append(",\"message\":\"").append(c.message().replace("\"","'")).append("\"}");}Log.info("MINDUSTRY_RESULT @",s.append("]}").toString());Core.app.exit();}private static void req(boolean v,String m){if(!v)throw new AssertionError(m);}private interface X{void run()throws Exception;}private record C(String name,boolean passed,String message){}}